-- השלמת משפטים: זכר ונקבה עם ניקוד
-- יש להריץ אחרי sentence_completion.sql. הרצה חוזרת לא תכפיל משפטים.

insert into public.sentencecompletion
  (question, answer_a, answer_b, answer_c, answer_d, correct_answer,
   explanation_he, explanation_fa, translation_fa, difficulty, topic)
select v.*
from (values
  ('שָׂרָה, ___ גָּרָה בִּירוּשָׁלַיִם?', 'אַתֶּן', 'אַתְּ', 'אַתָּה', 'אַתֶּם', 'b', 'פונים לאישה בגוף שני: אַתְּ (at). לגבר: אַתָּה (atá). גם הפועל גָּרָה בנקבה.', 'برای خطاب به زن «אַתְּ» (اَت) و به مرد «אַתָּה» (اَتا) می‌گوییم. فعل «גָּרָה» هم مؤنث است.', 'سارا، تو در اورشلیم زندگی می‌کنی؟', 'easy', 'gender'),
  ('יוֹסִי, מָה אַתָּה ___ לֶאֱכֹל?', 'רוֹצִים', 'רוֹצוֹת', 'רוֹצֶה', 'רוֹצָה', 'c', 'יוֹסִי ו''אַתָּה'' – זכר, ולכן רוֹצֶה (rotsé, בסגול). לנקבה: רוֹצָה (rotsá, בקמץ). בלי ניקוד שתיהן ''רוצה''.', '«יוֹסִי» اسم پسر است و «אַתָּה» مذکر، پس «רוֹצֶה» (روتسه). برای زن «רוֹצָה» (روتسا). بدون نیکود هر دو «רוצה» نوشته می‌شوند.', 'یوسی، چه می‌خواهی بخوری؟', 'easy', 'gender'),
  ('דָּנָה ___ קָפֶה בַּבֹּקֶר.', 'שׁוֹתֶה', 'שׁוֹתִים', 'שׁוֹתוֹת', 'שׁוֹתָה', 'd', 'דָּנָה היא אישה, ולכן שׁוֹתָה (shotá, בקמץ). לגבר: שׁוֹתֶה (shoté, בסגול). בלי ניקוד שתיהן ''שותה''.', '«דָּנָה» اسم دختر است، پس «שׁוֹתָה» (شوتا). برای مرد «שׁוֹתֶה» (شوته). بدون نیکود هر دو «שותה» نوشته می‌شوند و فقط تلفظشان فرق دارد.', 'دانا صبح‌ها قهوه می‌نوشد.', 'easy', 'gender'),
  ('הַיַּלְדָּה ___ טֶלֶוִיזְיָה בַּסָּלוֹן.', 'רוֹאָה', 'רוֹאֶה', 'רוֹאִים', 'רוֹאוֹת', 'a', '''יַלְדָּה'' היא נקבה: רוֹאָה (roá). לזכר: ''הַיֶּלֶד רוֹאֶה'' (roé).', '«יַלְדָּה» (دختر) مؤنث است: «רוֹאָה» (روآ). برای پسر: «הַיֶּלֶד רוֹאֶה» (روئه).', 'دختر در پذیرایی تلویزیون تماشا می‌کند.', 'easy', 'gender'),
  ('אַבָּא שֶׁלִּי ___ אֹכֶל בַּשּׁוּק כָּל יוֹם שִׁשִּׁי.', 'קוֹנוֹת', 'קוֹנֶה', 'קוֹנָה', 'קוֹנִים', 'b', '''אַבָּא'' – זכר: קוֹנֶה (koné). לנקבה: ''אִמָּא קוֹנָה'' (koná).', '«אַבָּא» (پدر) مذکر است: «קוֹנֶה» (کونه). برای مادر: «אִמָּא קוֹנָה» (کونا).', 'پدرم هر جمعه از بازار غذا می‌خرد.', 'easy', 'gender'),
  ('רִינָה הִיא ___ לְעִבְרִית.', 'מוֹרִים', 'מוֹרוֹת', 'מוֹרָה', 'מוֹרֶה', 'c', 'רִינָה היא אישה: מוֹרָה (morá). גבר: מוֹרֶה (moré). בלי ניקוד שתיהן ''מורה''.', 'رینا زن است: «מוֹרָה» (مورا). برای مرد: «מוֹרֶה» (موره). بدون نیکود هر دو «מורה» نوشته می‌شوند.', 'رینا معلم عبری است.', 'easy', 'gender'),
  ('הַדִּירָה הַחֲדָשָׁה ___ מְאוֹד.', 'יָפֶה', 'יָפִים', 'יָפוֹת', 'יָפָה', 'd', '''דִּירָה'' היא נקבה, ולכן יָפָה (yafá). לזכר: ''הַבַּיִת יָפֶה'' (yafé).', '«דִּירָה» (آپارتمان) مؤنث است، پس «יָפָה» (یافا). برای مذکر: «הַבַּיִת יָפֶה» (یافه).', 'آپارتمان جدید خیلی قشنگ است.', 'medium', 'gender'),
  ('הַמִּבְחָן הָיָה ___.', 'קָשֶׁה', 'קָשָׁה', 'קָשִׁים', 'קָשׁוֹת', 'a', '''מִבְחָן'' הוא זכר, ולכן קָשֶׁה (kashé). לנקבה: ''הַשְּׁאֵלָה קָשָׁה'' (kashá).', '«מִבְחָן» (امتحان) مذکر است، پس «קָשֶׁה» (کاشه). برای مؤنث: «הַשְּׁאֵלָה קָשָׁה» (کاشا).', 'امتحان سخت بود.', 'medium', 'gender'),
  ('שִׁירָה, אַתְּ ___ עִבְרִית?', 'מְדַבְּרוֹת', 'מְדַבֶּרֶת', 'מְדַבֵּר', 'מְדַבְּרִים', 'b', '''אַתְּ'' – נקבה, ובהווה: מְדַבֶּרֶת (medabéret). לגבר: מְדַבֵּר (medabér).', 'برای «אַתְּ» (مؤنث) در زمان حال: «מְדַבֶּרֶת» (مِدَبِرِت). برای مرد: «מְדַבֵּר» (مِدَبِر).', 'شیرا، تو عبری صحبت می‌کنی؟', 'medium', 'gender'),
  ('מִיכָאֵל, אֵיפֹה הַתִּיק ___?', 'לְךָ', 'אוֹתְךָ', 'שֶׁלְּךָ', 'שֶׁלָּךְ', 'c', 'לגבר: שֶׁלְּךָ (shelchá). לאישה: שֶׁלָּךְ (shelách). בלי ניקוד שתיהן ''שלך''.', 'برای مرد «שֶׁלְּךָ» (شِلخا) و برای زن «שֶׁלָּךְ» (شِلاخ). بدون نیکود هر دو «שלך» نوشته می‌شوند.', 'میخائیل، کیفت کجاست؟', 'medium', 'gender'),
  ('רוּתִי, הַשִּׂמְלָה ___ יָפָה מְאוֹד!', 'שֶׁלְּךָ', 'לָךְ', 'אוֹתָךְ', 'שֶׁלָּךְ', 'd', 'פונים לרוּתִי – אישה, ולכן שֶׁלָּךְ (shelách). לגבר: שֶׁלְּךָ (shelchá).', 'روتی زن است، پس «שֶׁלָּךְ» (شِلاخ) یعنی «مال تو» برای مؤنث. برای مرد: «שֶׁלְּךָ» (شِلخا).', 'روتی، لباست خیلی قشنگ است!', 'medium', 'gender'),
  ('אַבָּא, יֵשׁ ___ זְמַן לַעֲזֹר לִי?', 'לְךָ', 'לָךְ', 'אוֹתְךָ', 'שֶׁלְּךָ', 'a', '''אַבָּא'' – זכר: לְךָ (lechá). לאִמָּא נאמר: לָךְ (lach). ''יֵשׁ לְךָ'' = do you have.', 'برای پدر (مذکر): «לְךָ» (لِخا). برای مادر (مؤنث): «לָךְ» (لاخ). «יֵשׁ לְךָ» یعنی «داری».', 'بابا، وقت داری کمکم کنی؟', 'medium', 'gender'),
  ('אִמָּא, אֲנִי אוֹהֵב ___!', 'לָךְ', 'אוֹתָךְ', 'אוֹתְךָ', 'שֶׁלָּךְ', 'b', 'פונים לאִמָּא – נקבה: אוֹתָךְ (otách). לאַבָּא: אוֹתְךָ (otchá). אחרי ''אוֹהֵב'' בא מושא ישיר עם אוֹת־.', 'به مادر (مؤنث) «אוֹתָךְ» (اوتاخ) و به پدر «אוֹתְךָ» (اوتخا) می‌گوییم. بعد از «אוֹהֵב» مفعول مستقیم با «אוֹת־» می‌آید.', 'مامان، دوستت دارم!', 'medium', 'gender'),
  ('מִירִי, ___ לִי בְּבַקָּשָׁה אֶת הַמֶּלַח.', 'תְּנוּ', 'תִּתֵּן', 'תְּנִי', 'תֵּן', 'c', 'בציווי לאישה מוסיפים ־ִי: תְּנִי (tní). לגבר: תֵּן (ten). לרבים: תְּנוּ (tnu).', 'در فعل امر برای زن «־ִי» اضافه می‌شود: «תְּנִי» (تِنی). برای مرد «תֵּן» (تِن) و برای جمع «תְּנוּ» (تِنو).', 'میری، لطفاً نمک را به من بده.', 'medium', 'gender'),
  ('מֹשֶׁה, ___ לְכָאן רֶגַע!', 'בּוֹאִי', 'בּוֹאוּ', 'בָּאָה', 'בּוֹא', 'd', 'לגבר: בּוֹא (bo). לאישה: בּוֹאִי (bói). לרבים: בּוֹאוּ (bóu).', 'برای مرد «בּוֹא» (بو)، برای زن «בּוֹאִי» (بوئی) و برای جمع «בּוֹאוּ» (بوئو).', 'موشه، یک لحظه بیا اینجا!', 'medium', 'gender'),
  ('נוֹעָה, מָה אַתְּ ___ אֶתְמוֹל בָּעֶרֶב?', 'אָכַלְתְּ', 'אָכַלְתָּ', 'אָכַלְתֶּם', 'אָכַלְתֶּן', 'a', '''אַתְּ'' בעבר: אָכַלְתְּ (achált), עם שווא בתָּ"ו. לגבר: אָכַלְתָּ (achálta), עם קמץ. בלי ניקוד שתיהן ''אכלת''.', 'برای «אַתְּ» (تو، مؤنث) در گذشته: «אָכַלְתְּ» (آخَلت) و برای «אַתָּה» (مذکر): «אָכַלְתָּ» (آخَلتا). بدون نیکود هر دو «אכלת» نوشته می‌شوند.', 'نوعا، دیروز عصر چه خوردی؟', 'hard', 'gender'),
  ('דָּוִד, אַתָּה ___ אֶת הַחֲדָשׁוֹת?', 'רָאִיתֶן', 'רָאִיתָ', 'רָאִית', 'רָאִיתֶם', 'b', '''אַתָּה'' בעבר: רָאִיתָ (raíta). לאישה: רָאִית (raít). בלי ניקוד שתיהן ''ראית''.', 'برای «אַתָּה» در گذشته: «רָאִיתָ» (رائیتا). برای «אַתְּ»: «רָאִית» (رائیت). بدون نیکود هر دو «ראית» نوشته می‌شوند.', 'داوید، اخبار را دیدی؟', 'hard', 'gender')
) as v(question, answer_a, answer_b, answer_c, answer_d, correct_answer,
       explanation_he, explanation_fa, translation_fa, difficulty, topic)
where not exists (
  select 1 from public.sentencecompletion s where s.question = v.question
);
